command:
set -euo pipefail
EXPECTED=56813b27f6dc1f93d4899974ffd47a1528d8b6b8
test "$(git rev-parse HEAD)" = "$EXPECTED"
git fetch -q origin mvp/environment-controller
test "$(git rev-parse origin/mvp/environment-controller)" = "$EXPECTED"
test -z "$(git status --porcelain)"
python3 - <<'PY'
from pathlib import Path
path = Path('src/climate/rf433/Rf433RmtLoopback.cpp')
text = path.read_text(encoding='utf-8')
text = text.replace('#include <esp_err.h>\n', '#include <esp_err.h>\n#include <esp_log.h>\n', 1)
needle = '''  rmt_receive_config_t receive_config{};
  receive_config.signal_range_min_ns = kRxMinimumSignalNs;
  receive_config.signal_range_max_ns = kRxMaximumSignalNs;
  if (rmt_receive(rx_channel_,
                  rx_symbols_.data(),
                  rx_symbols_.size() * sizeof(rx_symbols_[0]),
                  &receive_config) != ESP_OK) {
    ++diagnostics_.rx_arm_errors;
    return false;
  }
'''
replacement = '''  struct RxProbeConfig {
    std::uint32_t min_ns;
    std::uint32_t max_ns;
  };
  constexpr std::array<RxProbeConfig, 6U> kProbeConfigs{{
      {20'000U, 300'000'000U},
      {100'000U, 300'000'000U},
      {20'000U, 100'000'000U},
      {100'000U, 100'000'000U},
      {100'000U, 50'000'000U},
      {200'000U, 20'000'000U},
  }};
  esp_err_t rx_arm_status = ESP_ERR_INVALID_ARG;
  for (std::size_t probe_index = 0U; probe_index < kProbeConfigs.size(); ++probe_index) {
    rmt_receive_config_t receive_config{};
    receive_config.signal_range_min_ns = kProbeConfigs[probe_index].min_ns;
    receive_config.signal_range_max_ns = kProbeConfigs[probe_index].max_ns;
    rx_arm_status = rmt_receive(rx_channel_,
                                rx_symbols_.data(),
                                rx_symbols_.size() * sizeof(rx_symbols_[0]),
                                &receive_config);
    ESP_LOGI("rf433_rmt",
             "rx_probe idx=%u min_ns=%lu max_ns=%lu err=%s code=0x%x",
             static_cast<unsigned>(probe_index),
             static_cast<unsigned long>(kProbeConfigs[probe_index].min_ns),
             static_cast<unsigned long>(kProbeConfigs[probe_index].max_ns),
             esp_err_to_name(rx_arm_status), static_cast<unsigned>(rx_arm_status));
    if (rx_arm_status == ESP_OK) {
      break;
    }
  }
  if (rx_arm_status != ESP_OK) {
    ++diagnostics_.rx_arm_errors;
    return false;
  }
'''
if needle not in text:
    raise SystemExit('rmt_receive probe anchor not found')
path.write_text(text.replace(needle, replacement, 1), encoding='utf-8')
PY
git diff --check
PORT=$(.venv/bin/python -c 'from tools.stage27c_soak import detect_ch340_port; print(detect_ch340_port())')
echo "STAGE28B_PORT=$PORT"
export PORT GROWBOX_FIRMWARE_GIT_SHA="$EXPECTED" GROWBOX_STAGE27_SD_ENABLED=1 GROWBOX_STAGE27_FLASH_FALLBACK_ENABLED=1 GROWBOX_SD_CMD0_PRECONDITION=0 GROWBOX_RF433_LOOPBACK_ENABLED=1 GROWBOX_RF433_LOOPBACK_AUTO_SMOKE=1 GROWBOX_RF433_TX_GPIO=8 GROWBOX_RF433_RX_GPIO=14 STAGE27C_BUILD_DIR=build/idf-stage28b-rf-rx-config-probe-v1
scripts/stage27c_crowpanel.sh flash
OUT=/tmp/stage28b-rf-rx-config-probe-v1
rm -rf "$OUT"
.venv/bin/python tools/stage27c_soak.py --port "$PORT" --output-dir "$OUT" --duration 60 --progress-seconds 20 --expected-sha "$EXPECTED" --require-sd --strict
.venv/bin/python - "$OUT" <<'PY'
from pathlib import Path
import re, sys
out = Path(sys.argv[1])
lines = []
rf = []
for p in sorted(out.glob('raw-*.log')):
    for line in p.read_text(encoding='utf-8', errors='replace').splitlines():
        if 'rf433_rmt: rx_probe ' in line:
            lines.append(line)
        if 'rf433_loopback_v=1 ' in line:
            rf.append(line)
assert lines, 'no rx_probe lines captured'
print('STAGE28B_RX_PROBE_LINES', len(lines))
for line in lines:
    print(line)
accepted = [line for line in lines if 'code=0x0' in line]
if accepted:
    print('STAGE28B_RX_PROBE_ACCEPTED', accepted[0])
else:
    print('STAGE28B_RX_PROBE_NO_ACCEPTED')
if rf:
    print('STAGE28B_RX_PROBE_RF_RESULT', rf[-1])
PY
git reset --hard "$EXPECTED"
test -z "$(git status --porcelain)"
printf 'STAGE28B_RF_RX_CONFIG_PROBE_OK\n'
